import axios from "axios";
const generateGraphDataRipe = async(graphData, metric, group, between) => {
    let data = [];
    let labelData = [];
    let Dataset = [];
    let Between = between;
    console.log('data to be iterated');
    console.log(graphData.data);

    const generate =  async() => {
        let FullData = [[], []];
        let i = 0;
        if (Between) {
            console.log('between time')
            let bdata = [[], []];
            let labelText = '';
            for (let i = 0; i < 2; i++) {
                bdata[0].push(graphData[i][0][0].country);
            }
            console.log('graph length')
            console.log(graphData[0][0][0].length)
            for (let i = 0; i <2; i++) {

                switch (metric) {
                    case 'avg_download_latency_ms':
                        console.log(graphData[i][0][0].avg_download_latency_ms)
                        console.log(bdata);
                        bdata[1].push(graphData[i][0][0].avg_download_latency_ms);
                        labelText = 'Average Download Latency ms'
                        console.log(labelText);
                        break;
                    case 'avg_download_speed_mbps':
                        console.log(graphData[i][0][0]);
                        bdata[1].push(graphData[i][0][0].avg_download_speed_mbps);
                        labelText = 'Average Download Speed mbps'
                        break;
                    case 'avg_packet_loss':
                        bdata[1].push(graphData[i][0][0].avg_packet_loss);
                        labelText = 'Average Packet Loss'
                        break;
                    case 'avg_upload_speed_mbps':
                        bdata[1].push(graphData[i][0][0].avg_upload_speed_mbps);
                        labelText = 'Average Upload Speed mbps'
                        break;
                    case 'avg_upload_latency_ms':
                        bdata[1].push(graphData[i][0][0].avg_upload_latency_ms);
                        labelText = 'Average Upload Latency ms'
                        break;
                    case 'download_num_tests':
                        bdata[1].push(graphData[i][0][0].download_num_tests);
                        labelText = 'Number of download tests'
                        break;
                    case 'upload_num_tests':
                        bdata[1].push(graphData[i][0][0].upload_num_tests);
                        labelText = 'Number of upload tests'
                        break;
                }
                

            }
                console.log('data to be mapped')
                console.log(bdata);
                console.log(bdata[1]);
                bdata =  arrayMapper(labelText, bdata[0], bdata[1]);
                console.log('this will be returned');
                console.log(bdata);
                return bdata;

        } else {

            data = [];
            for (let i = 0; i < graphData.length; i++) {
                switch (metric) {
                    case 'avg_rtt':
                        Dataset = graphData[i].map((item) => item.avg_rtt);
                        switch (group) {
                            case 'month':
                                console.log(graphData.data[i][0]);
                                labelData = graphData.data[i].map((item) => item.month);
                                data =  await arrayMapper('Average Round Trip Time per month', labelData, Dataset);
                                break;
                            case 'year':
                                labelData = graphData.data[i].map((item) => item.year);
                                data =  await arrayMapper('Average Round Trip Time per year', labelData, Dataset);
                                break;
                        }
                    break;

                    case 'max_rtt':
                        Dataset = graphData[i].map((item) => item.avg_rtt);
                        switch (group) {
                            case 'month':
                                labelData = graphData.data[i].map((item) => item.month);
                                data =  await arrayMapper('Average Round Trip Time per month', labelData, Dataset);
                                break;
                            case 'year':
                                labelData = graphData.data[i].map((item) => item.year);
                                data =  await arrayMapper('Average Round Trip Time per year', labelData, Dataset);
                                break;
                        }
                    break;

                    case 'min_rtt':
                        Dataset = graphData[i][0].map((item) => item.avg_rtt);
                        switch (group) {
                            case 'month':
                                labelData = graphData[i][0].map((item) => item.month);
                                data =  await arrayMapper('Average Round Trip Time per month', labelData, Dataset);
                                break;
                            case 'year':
                                labelData = graphData[i][0].map((item) => item.year);
                                data =  await arrayMapper('Average Round Trip Time per year', labelData, Dataset);
                                break;
                        }
                    break;
                    

                }
                FullData[i] = data;
            }

            
        }
        console.log('FULLDATA')
        console.log(FullData);
        return FullData;
    }



    const arrayMapper =  async(labelText, labelData, dataSetData) => {
        const data = {
            labels: labelData,
            datasets: [
                {
                    label: labelText,
                    data: dataSetData,
                    backgroundColor: ["#000"],
                    fill: false,
                    borderColor: "black",
                    borderWidth: 2,
                },
            ],
        };
        console.log("mapped array");
        console.log(data);
        return data;
    };

    return generate();

}

